interface LetterViewProps {
  content: string | null;
  onEdit: () => void;
  onReset: () => void;
  design: FullDesign;
}

const useHandwriting = (text: string, isReading: boolean) => {
  const [displayedText, setDisplayedText] = useState('');
  const [isComplete, setIsComplete] = useState(false);
  const indexRef = useRef(0);

  useEffect(() => {
    setDisplayedText('');
    setIsComplete(false);
    indexRef.current = 0;
  }, [text, isReading]);

  useEffect(() => {
    if (!isReading) return;

    const interval = setInterval(() => {
      if (indexRef.current < text.length) {
        const char = text.charAt(indexRef.current);
        setDisplayedText(prev => prev + char);
        indexRef.current++;
      } else {
        setIsComplete(true);
        clearInterval(interval);
      }
    }, 35);

    return () => clearInterval(interval);
  }, [isReading, text]);

  return { displayedText, isComplete };
};

export const LetterView: React.FC<LetterViewProps> = ({ content, onEdit, onReset, design }) => {
  const [stage, setStage] = useState<'closed' | 'opening' | 'reading'>('closed');
  const { displayedText, isComplete } = useHandwriting(content || '', stage === 'reading');

  if (!content) return null;

  const handleOpenEnvelope = () => {
    setStage('opening');
    setTimeout(() => {
      setStage('reading');
    }, 1600);
  };

  const handleShare = async () => {
    const shareUrl = `${window.location.origin}${window.location.pathname}?note=${encodeURIComponent(content)}`;
    if (navigator.share) {
      try {
        await navigator.share({
          title: 'A Custom Letter for You',
          text: 'I wrote something special for you...',
          url: shareUrl,
        });
      } catch (err) { console.log(err); }
    } else {
      await navigator.clipboard.writeText(shareUrl);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <div className="flex flex-col items-center w-full min-h-[85vh] justify-center relative py-10 animate-fade-in">

      <div className={`transition-all duration-1000 absolute inset-0 flex items-center justify-center z-10
        ${stage === 'reading' ? 'opacity-0 pointer-events-none scale-150' : 'opacity-100 scale-100'}`}
      >
        <Envelope 
          isOpened={stage !== 'closed'} 
          onOpen={handleOpenEnvelope} 
          design={design.envelope}
          paperDesign={design.letter}
        />
      </div>

      <div 
        className={`w-full max-w-3xl transition-all duration-1000 transform
        ${stage === 'reading' ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-20 scale-95 pointer-events-none'}`}
      >
        <div className={`${design.letter.paperBg} ${design.letter.borderColor} border-2 p-8 md:p-16 rounded shadow-2xl mb-8 relative overflow-hidden min-h-[600px] flex flex-col`}>

          <div className={`absolute inset-0 pointer-events-none ${design.letter.paperTexture} bg-repeat`} 
               style={{ backgroundImage: 'url("https://www.transparenttextures.com/patterns/cream-paper.png")' }}>
          </div>

          <div className="relative z-10 flex-grow">
            <div className={`${design.letter.fontFamily} ${design.letter.textColor} text-2xl md:text-3xl leading-[2.2] tracking-wide whitespace-pre-wrap max-w-2xl mx-auto`}>
              {displayedText}
              {!isComplete && stage === 'reading' && (
                <span className="inline-block w-0.5 h-8 bg-current animate-pulse ml-0.5 align-middle -mt-2"></span>
              )}
            </div>
          </div>
        </div>

        <div className={`flex flex-wrap justify-center gap-4 transition-opacity duration-1000 delay-1000 ${stage === 'reading' ? 'opacity-100' : 'opacity-0'}`}>
          <Button variant="secondary" onClick={onEdit}>
            Back to Studio
          </Button>
          <Button onClick={handleShare}>
            Share Link
          </Button>
          <Button variant="ghost" onClick={onReset} className="text-stone-500">
            Write New
          </Button>
        </div>
      </div>
    </div>
  );
};

