import React, { useState, useEffect, useCallback } from 'react';

const PATHS = {
  ROSE: "M50 50 C 70 30, 110 30, 120 60 S 90 100, 60 90 S 30 60, 60 50 M 60 50 C 50 20, 90 -10, 130 10 S 160 70, 130 100 S 80 120, 50 90 M 60 50 C 10 50, -10 100, 30 140 S 100 160, 130 130",
  VINE: "M0 200 C 50 150, 100 250, 150 150 S 250 50, 300 100 S 350 250, 450 150 S 550 50, 600 100",
  HEART: "M100 100 C 100 50, 50 50, 50 100 C 50 150, 100 200, 150 250 C 200 200, 250 150, 250 100 C 250 50, 200 50, 200 100",
  LILY: "M100 200 Q 80 150, 100 100 Q 120 150, 100 200 M 100 200 Q 150 180, 200 200 Q 150 220, 100 200 M 100 200 Q 120 250, 100 300 Q 80 250, 100 200 M 100 200 Q 50 220, 0 200 Q 50 180, 100 200",
  LAVENDER: "M50 300 Q 70 200, 50 100 M 50 120 L 70 110 M 50 140 L 30 130 M 50 160 L 70 150 M 50 180 L 30 170"
};

const COLORS = [
  'text-rose-200', 
  'text-rose-300', 
  'text-sage-200', 
  'text-sage-300', 
  'text-rose-100', 
  'text-emerald-100'
];

interface BloomConfig {
  id: string;
  path: string;
  x: number;
  y: number;
  rotation: number;
  scale: number;
  color: string;
  duration: number;
  flip: boolean;
}

const BloomInstance: React.FC<{ index: number }> = ({ index }) => {
  const [config, setConfig] = useState<BloomConfig | null>(null);
  const [key, setKey] = useState(0);

  const generateRandomConfig = useCallback((): BloomConfig => {
    const side = Math.random() > 0.5 ? 'left' : 'right';
    const typeKeys = Object.keys(PATHS) as Array<keyof typeof PATHS>;
    const type = typeKeys[Math.floor(Math.random() * typeKeys.length)];

    return {
      id: `${index}-${Date.now()}`,
      path: PATHS[type],
      x: side === 'left' ? Math.random() * 200 - 100 : 800 + Math.random() * 200,
      y: Math.random() * 900,
      rotation: Math.random() * 360,
      scale: 0.6 + Math.random() * 1.4,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
      duration: 15 + Math.random() * 10,
      flip: side === 'right'
    };
  }, [index]);

  useEffect(() => {
    setConfig(generateRandomConfig());
  }, [generateRandomConfig]);

  const handleAnimationEnd = () => {
    setKey(prev => prev + 1);
    setConfig(generateRandomConfig());
  };

  if (!config) return null;

  return (
    <g 
      key={key}
      onAnimationEnd={handleAnimationEnd}
      style={{
        transform: `translate(${config.x}px, ${config.y}px) rotate(${config.rotation}deg) scale(${config.scale}) ${config.flip ? 'scaleX(-1)' : ''}`,
        transformOrigin: 'center',
        animation: `cycleAnimation ${config.duration}s linear forwards`
      }}
    >
      <path
        className={`animate-draw ${config.color}`}
        d={config.path}
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinecap="round"
        fill="none"
        style={{
          strokeDasharray: 2000,
          strokeDashoffset: 2000,
          animation: `drawAnimation ${config.duration * 0.4}s cubic-bezier(0.4, 0, 0.2, 1) forwards`
        }}
      />
    </g>
  );
};

